SINA_SMART["physio-vestibular"] = {"lecture":"physio-vestibular","title":"The vestibular system","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio-vestibular:e0","text":"Otolith organs: linear acceleration and gravity; canals: angular acceleration.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"physio-vestibular:s1","text":"Describe and explain: Balance and the vestibular apparatus","topic":"Balance and the vestibular apparatus","sec":1,"importance":"standard","highYield":"untested"},{"id":"physio-vestibular:e1","text":"Cupula in canals; otolithic membrane in maculae.","topic":"Hair cells, maculae and cristae","sec":2,"importance":"core","highYield":"untested"},{"id":"physio-vestibular:e2","text":"Bending toward the tallest stereocilium depolarises.","topic":"Hair cells, maculae and cristae","sec":2,"importance":"core","highYield":"untested"},{"id":"physio-vestibular:e3","text":"Utricle horizontal, saccule vertical.","topic":"Hair cells, maculae and cristae","sec":2,"importance":"core","highYield":"untested"},{"id":"physio-vestibular:e4","text":"Start of rotation: crista tilts opposite; stop: same way; steady: rest.","topic":"Hair cells, maculae and cristae","sec":2,"importance":"core","highYield":"untested"},{"id":"physio-vestibular:e5","text":"Turning right excites the right lateral canal.","topic":"Hair cells, maculae and cristae","sec":2,"importance":"core","highYield":"untested"},{"id":"physio-vestibular:e6","text":"Superior division: lateral and anterior cristae, utricle; inferior: saccule, posterior crista.","topic":"The vestibular nerve and central pathways","sec":3,"importance":"core","highYield":"untested"},{"id":"physio-vestibular:e7","text":"Vestibular nerve enters at the cerebellopontine angle.","topic":"The vestibular nerve and central pathways","sec":3,"importance":"core","highYield":"untested"},{"id":"physio-vestibular:e8","text":"MLF links vestibular nuclei to III, IV, VI.","topic":"Eye reflexes and disorders","sec":4,"importance":"core","highYield":"untested"},{"id":"physio-vestibular:e9","text":"Caloric test: lateral canal; MLF lesion: internuclear ophthalmoplegia.","topic":"Eye reflexes and disorders","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1xq3cvs":"a","sftm18":"a","1bpwknh":"a","6hktse":"a","14vll5v":"a","1nxji20":"a","tnib2w":"a","157ylul":"a","1o64ro4":"a","1r4wcfa":"a","1xtybdj":"a","10e4cje":"a","1d0h3nm":"a","r9q2ya":"a","72d77d":"a","1dkxrrq":"a","192j0p9":"a","r8sodx":"a","mnt2ad":"a","ybf84y":"a","40f1oa":"a","al0c9l":"a","7b6i6s":"a","1dwojvr":"a","1obt12":"x","r12uoy":"x","ekcv92":"x"},"mapCounts":{"verified":0,"auto":24,"ambiguous":0,"missing":3},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio-vestibular:e0":{"s":0,"u":["Otolith organs: linear acceleration and gravity; canals: angular acceleration.","The otolith organs (utricle and saccule) feel gravity and linear acceleration ; the semicircular canals feel rotation ."],"dp":[]},"physio-vestibular:s1":{"s":1,"u":["Balance combines vestibular, visual and proprioceptive input, integrated mainly by the cerebellum , below consciousness.","Kinesthesis is the somatosensory sense of body-part position; equilibrium is vestibular."],"dp":[]},"physio-vestibular:e1":{"s":2,"u":["Cupula in canals; otolithic membrane in maculae.","Stereocilia sit in a gel: the otolithic membrane (maculae) or the cupula (canals).","Gel: Maculae (utricle, saccule) = Otolithic membrane with otoconia; Cristae (canals) = Cupula."],"dp":[]},"physio-vestibular:e2":{"s":2,"u":["Bending toward the tallest stereocilium depolarises.","Bending toward the tallest row opens channels."],"dp":[]},"physio-vestibular:e3":{"s":2,"u":["Utricle horizontal, saccule vertical.","Orientation: Maculae (utricle, saccule) = Utricle horizontal, saccule vertical; Cristae (canals) = Three canals at right angles.","Gel: Maculae (utricle, saccule) = Otolithic membrane with otoconia; Cristae (canals) = Cupula."],"dp":[]},"physio-vestibular:e4":{"s":2,"u":["Start of rotation: crista tilts opposite; stop: same way; steady: rest.","Rotation: starting, the endolymph lags and tilts the crista opposite to the rotation; stopping, it tilts the same way; at steady speed the cupula returns to rest."],"dp":[{"h":"Why you feel dizzy after spinning then stopping","t":"During steady spinning the endolymph catches up and the cupula rests. When you stop suddenly, the endolymph keeps moving and bends the cupula the other way, so the canal signals rotation in the opposite direction even though you are still. Your eyes jerk (nystagmus) and the room seems to spin until the fluid settles. Source: the lecture's crista ampullaris slides."}]},"physio-vestibular:e5":{"s":2,"u":["Turning right excites the right lateral canal.","Turning right excites the right lateral canal and inhibits the left.","Orientation: Maculae (utricle, saccule) = Utricle horizontal, saccule vertical; Cristae (canals) = Three canals at right angles."],"dp":[]},"physio-vestibular:e6":{"s":3,"u":["Superior division: lateral and anterior cristae, utricle; inferior: saccule, posterior crista.","The superior division supplies the lateral and anterior cristae and most of the utricle; the inferior division supplies the saccule and the posterior crista via the singular nerve (foramen singulare)."],"dp":[]},"physio-vestibular:e7":{"s":3,"u":["Vestibular nerve enters at the cerebellopontine angle.","The nerve enters at the cerebellopontine angle and ends in the vestibular nuclei, projecting to motor nuclei, the cerebellum and the thalamus, then cortical areas 2v, 3a, 7 and the parieto-insular vestibular cortex."],"dp":[]},"physio-vestibular:e8":{"s":4,"u":["MLF links vestibular nuclei to III, IV, VI.","The MLF links the vestibular nuclei to the nuclei of III, IV and VI and upper spinal motor neurons, keeping gaze fixed."],"dp":[]},"physio-vestibular:e9":{"s":4,"u":["Caloric test: lateral canal; MLF lesion: internuclear ophthalmoplegia.","Internuclear ophthalmoplegia: MLF lesion: poor ipsilateral adduction, abducting nystagmus; seen in MS.","Caloric test: Warm or cold water stimulates the lateral canal crista."],"dp":[]}},"meta":{"1xq3cvs":{"a":"recall","vg":"physio-vestibular:s1/recall/1"},"sftm18":{"a":"recall","vg":"physio-vestibular:s1/recall/2"},"1bpwknh":{"a":"recall","vg":"physio-vestibular:e0/recall/1"},"6hktse":{"a":"recall","vg":"physio-vestibular:e0/recall/1"},"14vll5v":{"a":"recall","vg":"physio-vestibular:e1/recall/1"},"1nxji20":{"a":"recall","vg":"physio-vestibular:e2/recall/1"},"tnib2w":{"a":"recall","vg":"physio-vestibular:e4/recall/1"},"157ylul":{"a":"recall","vg":"physio-vestibular:e4/recall/2"},"1o64ro4":{"a":"recall","vg":"physio-vestibular:e5/recall/1"},"1r4wcfa":{"a":"recall","vg":"physio-vestibular:e5/recall/2"},"1xtybdj":{"a":"recall","vg":"physio-vestibular:e1/recall/2"},"10e4cje":{"a":"recall","vg":"physio-vestibular:e4/recall/3"},"1d0h3nm":{"a":"recall","vg":"physio-vestibular:e6/recall/1"},"r9q2ya":{"a":"recall","vg":"physio-vestibular:e6/recall/2"},"72d77d":{"a":"recall","vg":"physio-vestibular:e7/recall/1"},"1dkxrrq":{"a":"recall","vg":"physio-vestibular:e7/recall/2"},"192j0p9":{"a":"recall","vg":"physio-vestibular:e8/recall/1"},"r8sodx":{"a":"recall","vg":"physio-vestibular:e9/recall/1"},"mnt2ad":{"a":"recall","vg":"physio-vestibular:s1/recall/3"},"ybf84y":{"a":"application","vg":"physio-vestibular:e9/application/1"},"40f1oa":{"a":"recall","vg":"physio-vestibular:e9/recall/2"},"al0c9l":{"a":"recall","vg":"physio-vestibular:s1/recall/4"},"7b6i6s":{"a":"recall","vg":"physio-vestibular:e6/recall/3"},"1dwojvr":{"a":"recall","vg":"physio-vestibular:e7/recall/3"}},"explRev":"3fc26f96ce34"};
